import { useState, type FormEvent } from 'react';
import { Plus, Edit2, Trash2, RefreshCw, Loader2, Upload } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import I18nInput from '@/components/I18nInput';
import { useAdvantages, type IAdvantage } from '@/hooks/useAdvantages';
import { createI18nText, type I18nText } from '@/lib/i18n-text';
import { batchTranslateI18n } from '@/lib/translate';
import { Award, ShieldCheck, Settings, Wrench, Lightbulb, Zap, Globe, Target } from 'lucide-react';
import { toast } from 'sonner';
import { useI18n } from '@/i18n/I18nContext';
import PageBreadcrumb from '@/components/PageBreadcrumb';
import { useSyncService } from '@/context/SyncServiceContext';
import SyncStatusBadge from '@/components/SyncStatusBadge';

const ICONS = [
  { name: 'Award', icon: Award },
  { name: 'ShieldCheck', icon: ShieldCheck },
  { name: 'Settings', icon: Settings },
  { name: 'Wrench', icon: Wrench },
  { name: 'Lightbulb', icon: Lightbulb },
  { name: 'Zap', icon: Zap },
  { name: 'Globe', icon: Globe },
  { name: 'Target', icon: Target },
];

interface AdvForm {
  title: I18nText;
  description: I18nText;
  icon: string;
}

const emptyForm = (): AdvForm => ({
  title: createI18nText(''),
  description: createI18nText(''),
  icon: 'Award',
});

export default function AdminAdvantagesPage() {
  const { advantages, addAdvantage, updateAdvantage, deleteAdvantage, loading } = useAdvantages();
  const { adminT } = useI18n();
  const { markDirty, syncModule, syncJsonFile, getStatus } = useSyncService();
  const syncStatus = getStatus('advantages');
  const [dialogOpen, setDialogOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [form, setForm] = useState<AdvForm>(emptyForm());
  const [dialogTranslating, setDialogTranslating] = useState(false);
  const [dialogProgress, setDialogProgress] = useState({ current: 0, total: 0 });
  const [pageTranslating, setPageTranslating] = useState(false);
  const [pageProgress, setPageProgress] = useState({ current: 0, total: 0 });

  const resetForm = () => {
    setForm(emptyForm());
    setEditingId(null);
  };

  const openCreate = () => {
    resetForm();
    setDialogOpen(true);
  };

  const openEdit = (advantage: IAdvantage) => {
    setForm({
      title: advantage.title,
      description: advantage.description,
      icon: advantage.icon,
    });
    setEditingId(advantage.id);
    setDialogOpen(true);
  };

  const handleTranslateAll = async () => {
    const tasks = [
      { label: adminT('admin.title'), value: form.title, field: 'title' },
      { label: adminT('admin.description'), value: form.description, field: 'description' },
    ].filter((t) => t.value.en.trim());

    if (!tasks.length) {
      toast.error(adminT('admin.translateEnterEnFirst'));
      return;
    }
    setDialogTranslating(true);
    setDialogProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total) => {
        setDialogProgress({ current: cur, total });
      });
      const newForm = { ...form };
      const formDict = newForm as unknown as Record<string, I18nText>;
      for (let i = 0; i < results.length; i++) {
        const task = tasks[i];
        if (task && task.field && formDict[task.field]) {
          formDict[task.field] = results[i].value;
        }
      }
      setForm(newForm);
      const successCount = results.filter((r) => r.success).length;
      const failed = results.filter((r) => !r.success && !r.skipped);
      if (failed.length > 0) {
        toast.warning(`${adminT('admin.translatedNofM')} ${successCount}/${results.length}. ${adminT('admin.failed')}: ${failed.map((f) => f.label).join(', ')}`);
      } else {
        toast.success(adminT('admin.translatedAll'));
      }
    } catch {
      toast.error(adminT('admin.translateFailed'));
    } finally {
      setDialogTranslating(false);
      setDialogProgress({ current: 0, total: 0 });
    }
  };

  const handlePageTranslateAll = async () => {
    if (advantages.length === 0) {
      toast.warning(adminT('admin.noAdvantagesToTranslate'));
      return;
    }
    const fieldNames: Array<'title' | 'description'> = ['title', 'description'];
    const tasks = advantages.flatMap((a) =>
      fieldNames.map((f) => ({
        label: `${a.title.en.slice(0, 20)} / ${f}`,
        value: a[f],
      })),
    ).filter((t) => t.value.en.trim());

    if (tasks.length === 0) {
      toast.warning(adminT('admin.noEnglishContent'));
      return;
    }

    setPageTranslating(true);
    setPageProgress({ current: 0, total: tasks.length });
    try {
      const results = await batchTranslateI18n(tasks, (cur, total) => {
        setPageProgress({ current: cur, total });
      });

      let resultIdx = 0;
      for (const adv of advantages) {
        const updates: Partial<IAdvantage> = {};
        let changed = false;
        for (const f of fieldNames) {
          if (adv[f].en.trim()) {
            const r = results[resultIdx];
            if (r && !r.skipped && r.success) {
              updates[f] = r.value;
              changed = true;
            }
            resultIdx++;
          }
        }
        if (changed) {
          updateAdvantage(adv.id, { ...adv, ...updates });
          markDirty('advantages');
        }
      }

       const successCount = results.filter((r) => r.success).length;
       const failed = results.filter((r) => !r.success && !r.skipped);
       if (failed.length > 0) {
          toast.warning(`${adminT('admin.translatedNofM')} ${successCount}/${results.length}. ${failed.length} ${adminT('admin.failed')}`);
       } else {
          toast.success(`${adminT('admin.translationCompleted')}: ${successCount} ${adminT('admin.translatedFields')}`);
       }
     } catch {
       toast.error(adminT('admin.translateFailed'));
    } finally {
      setPageTranslating(false);
      setPageProgress({ current: 0, total: 0 });
    }
  };

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    if (!form.title.en.trim() || !form.description.en.trim()) {
       toast.error(adminT('admin.englishTitleDescRequired'));
      return;
    }

     if (editingId) {
        updateAdvantage(editingId, { title: form.title, description: form.description, icon: form.icon });
        markDirty('advantages');
        toast.success(adminT('admin.advantageUpdated'));
     } else {
        addAdvantage({ title: form.title, description: form.description, icon: form.icon, order: advantages.length + 1 });
        markDirty('advantages');
        toast.success(adminT('admin.advantageCreated'));
     }
    setDialogOpen(false);
    resetForm();
  };

  const handleDelete = (id: string) => {
    if (window.confirm(adminT('admin.deleteAdvantage'))) {
      deleteAdvantage(id);
      markDirty('advantages');
      toast.success(adminT('admin.advantageDeleted'));
    }
  };

  const getIconComponent = (iconName: string) => {
    const found = ICONS.find((i) => i.name === iconName);
    return found ? found.icon : Award;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center py-20">
        <div className="w-8 h-8 border-2 border-primary border-t-transparent rounded-full animate-spin" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Breadcrumb */}
      <PageBreadcrumb
         firstItem={{ label: adminT('admin.dashboard'), href: '/admin/dashboard', icon: 'dashboard' }}
         items={[
           { label: adminT('admin.advantages') },
         ]}
       />

       <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
         <div>
           <h1 className="text-2xl font-bold text-foreground">{adminT('admin.advantagesManagement')}</h1>
           <p className="text-sm text-muted-foreground mt-1">
             {adminT('admin.advantagesDisplayed')}: {advantages.length}
           </p>
         </div>
        <div className="flex items-center gap-2 flex-wrap">
          <SyncStatusBadge status={syncStatus} />
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              syncModule('advantages', 'Advantages', async (config) => {
                await syncJsonFile(
                  config,
                  'data/advantages.json',
                  advantages,
                  'Update advantages data'
                );
              })
            }
            disabled={syncStatus === 'syncing'}
            className="text-xs h-9"
          >
            <Upload className="size-3.5 mr-1.5" />
            Sync to GitHub
          </Button>
          <Button
            variant="outline"
            size="sm"
            onClick={handlePageTranslateAll}
            disabled={pageTranslating || advantages.length === 0}
            className="text-xs h-9"
          >
               {pageTranslating ? (
                 <>
                   <Loader2 className="size-3.5 mr-1.5 animate-spin" />
                   {adminT('admin.translating')} {pageProgress.current}/{pageProgress.total}...
                 </>
               ) : (
                 <>
                   <RefreshCw className="size-3.5 mr-1.5" />
                   {adminT('admin.translateAll')}
                 </>
               )}
          </Button>
          <Button onClick={openCreate} className="bg-primary hover:bg-primary/90 text-primary-foreground">
             <Plus className="size-4 mr-2" />
             {adminT('admin.addAdvantage')}
          </Button>
        </div>
      </div>

      <Card className="border-border/40 bg-card">
        <CardHeader className="pb-3">
           <CardTitle className="text-base">{adminT('admin.coreAdvantages')}</CardTitle>
        </CardHeader>
        <CardContent className="p-0">
          <div className="w-full overflow-x-auto">
            <Table>
              <TableHeader>
                 <TableRow>
                    <TableHead className="whitespace-nowrap w-16">{adminT('admin.icon')}</TableHead>
                    <TableHead className="whitespace-nowrap">{adminT('admin.nameEn')}</TableHead>
                    <TableHead className="whitespace-nowrap">{adminT('admin.descriptionEn')}</TableHead>
                    <TableHead className="whitespace-nowrap text-right">{adminT('admin.actions')}</TableHead>
                 </TableRow>
              </TableHeader>
              <TableBody>
                {advantages.length === 0 ? (
                   <TableRow>
                     <TableCell colSpan={4} className="text-center text-muted-foreground py-8">
                       {adminT('admin.noAdvantagesYet')}
                    </TableCell>
                  </TableRow>
                ) : (
                  advantages.map((adv) => {
                    const Icon = getIconComponent(adv.icon);
                    return (
                   <TableRow key={adv.id}>
                         <TableCell>
                          <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                            <Icon className="size-5 text-primary" />
                          </div>
                        </TableCell>
                        <TableCell className="font-medium">{adv.title.en}</TableCell>
                        <TableCell>
                          <span className="text-sm text-muted-foreground line-clamp-2 block max-w-md">
                            {adv.description.en}
                          </span>
                        </TableCell>
                        <TableCell className="text-right">
                          <div className="flex items-center justify-end gap-1">
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => openEdit(adv)}
                              className="h-8 w-8"
                            >
                              <Edit2 className="size-3.5" />
                            </Button>
                            <Button
                              variant="ghost"
                              size="icon"
                              onClick={() => handleDelete(adv.id)}
                              className="h-8 w-8 text-destructive hover:text-destructive hover:bg-destructive/10"
                            >
                              <Trash2 className="size-3.5" />
                            </Button>
                          </div>
                        </TableCell>
                      </TableRow>
                    );
                  })
                )}
              </TableBody>
            </Table>
          </div>
        </CardContent>
      </Card>

      {/* Dialog */}
      <Dialog open={dialogOpen} onOpenChange={setDialogOpen}>
        <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="flex items-center justify-between flex-wrap gap-2">
               <span>{editingId ? adminT('admin.editAdvantage') : adminT('admin.addAdvantage')}</span>
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={handleTranslateAll}
                disabled={dialogTranslating}
                className="text-xs h-8"
              >
                   {dialogTranslating ? (
                     <>
                       <Loader2 className="size-3.5 mr-1 animate-spin" />
                       {adminT('admin.translating')} {dialogProgress.current}/{dialogProgress.total}...
                     </>
                   ) : (
                     <>
                       <RefreshCw className="size-3.5 mr-1" />
                       {adminT('admin.translateAll')}
                     </>
                   )}
              </Button>
            </DialogTitle>
          </DialogHeader>
          <form onSubmit={handleSubmit} className="space-y-4">
             <I18nInput
               label={adminT('admin.title')}
               value={form.title}
               onChange={(v) => setForm({ ...form, title: v })}
               placeholder={adminT('admin.industryExperience')}
               
             />
             <I18nInput
               label={adminT('admin.description')}
               value={form.description}
               onChange={(v) => setForm({ ...form, description: v })}
               placeholder={adminT('admin.briefDescription')}
               multiline
               rows={3}
               
             />
              <div className="space-y-2">
                <label className="text-sm font-medium">{adminT('admin.icon')}</label>
               <Select value={form.icon} onValueChange={(v) => setForm({ ...form, icon: v })}>
                 <SelectTrigger>
                   <SelectValue placeholder={adminT('admin.selectIcon')} />
                </SelectTrigger>
                <SelectContent>
                  {ICONS.map((ic) => (
                    <SelectItem key={ic.name} value={ic.name}>
                      <div className="flex items-center gap-2">
                        <ic.icon className="size-4" />
                        {ic.name}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
             <DialogFooter className="pt-2">
               <Button type="button" variant="outline" onClick={() => setDialogOpen(false)}>
                 {adminT('admin.cancel')}
               </Button>
               <Button type="submit" className="bg-primary hover:bg-primary/90">
                 {editingId ? adminT('admin.saveChanges') : adminT('admin.addAdvantage')}
               </Button>
             </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  );
}
